package com.contenthub.config;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;
@Service public class JwtService{private final SecretKey key;public JwtService(@Value("${app.jwt.secret}")String secret){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String create(String subject){Date now=new Date();return Jwts.builder().subject(subject).issuedAt(now).expiration(new Date(now.getTime()+86400000)).signWith(key).compact();}public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}